import "./synopsis-facts-overview.css";

export interface SynopsisFact {
  label: string;
  value: string;
}

export interface SynopsisFactsOverviewProps {
  title: string;
  synopsis: string;
  facts: SynopsisFact[];
}

export function SynopsisFactsOverview({
  title,
  synopsis,
  facts,
}: SynopsisFactsOverviewProps) {
  return (
    <section className="tb-synopsis">
      <div className="tb-synopsis__statement">
        <h2>{title}</h2>
        <p>{synopsis}</p>
      </div>
      <dl className="tb-synopsis__facts">
        {facts.map((fact) => (
          <div key={`${fact.label}-${fact.value}`}>
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

.tb-synopsis {
  --tb-sfo-ink: #182029;
  --tb-sfo-paper: #edf1f3;
  --tb-sfo-panel: #d9e1e5;
  --tb-sfo-accent: #305cc0;
  container-type: inline-size;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(20rem, 100%), 1fr));
  gap: clamp(2.5rem, 6vw, 8rem);
  padding: clamp(2.5rem, 7%, 7rem) clamp(1.25rem, 7%, 7rem);
  color: var(--tb-sfo-ink);
  background: var(--tb-sfo-paper);
}

.tb-synopsis,
.tb-synopsis * {
  box-sizing: border-box;
}

.tb-synopsis__statement {
  align-self: center;
  min-width: 0;
}

.tb-synopsis__statement h2 {
  max-width: 46rem;
  margin: 0;
  font-size: clamp(2.6rem, 6vw, 5.8rem);
  font-size: clamp(2.6rem, 7.5cqi, 5.8rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}

.tb-synopsis__statement p {
  max-width: 48rem;
  margin: 2rem 0 0;
  font-size: clamp(1.1rem, 2cqi, 1.5rem);
  line-height: 1.5;
}

.tb-synopsis__facts {
  display: grid;
  align-content: start;
  grid-template-columns: repeat(auto-fit, minmax(min(10rem, 100%), 1fr));
  gap: 0.75rem;
  min-width: 0;
  margin: 0;
}

.tb-synopsis__facts > div {
  min-width: 0;
  padding: clamp(1.15rem, 2.5cqi, 1.75rem);
  background: var(--tb-sfo-panel);
}

.tb-synopsis__facts > div:first-child {
  background: var(--tb-sfo-accent);
  color: #f7f8fc;
}

.tb-synopsis__facts dt {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.tb-synopsis__facts dd {
  margin: 1.25rem 0 0;
  font-size: clamp(1rem, 2cqi, 1.28rem);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

@container (min-width: 48rem) {
  .tb-synopsis__facts > div:first-child {
    grid-column: span 2;
  }
}

@media (max-width: 800px) {
  .tb-synopsis {
    gap: 3rem;
  }
}
